/**
 * @fileoverview A client-side form for submitting a new company to the database.
 *
 * This component provides a complete form with fields for a company's name,
 * logo URL, description, and website. It uses `react-hook-form` for form
 * state management and `zod` for validation. Upon submission, it calls a
 * server action to add the company and provides user feedback via toasts.
 */
"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";

import { zodResolver } from "@hookform/resolvers/zod";
import { Link as LinkIcon,Loader2, PlusCircle } from "lucide-react";
import { z } from "zod";

import { addCompany as addCompanyAction } from "@/features/companies/actions/company.actions";
import type { Company } from "@/features/companies/types";
import { Button } from "@/shared/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/shared/components/ui/form";
import { Input } from "@/shared/components/ui/input";
import { Textarea } from "@/shared/components/ui/textarea";
import { useToast } from "@/shared/hooks/use-toast";
import { cn, slugify } from "@/shared/lib/utils";

/**
 * Zod schema for validating the company submission form fields.
 */
const companyFormSchema = z.object({
  name: z
    .string()
    .min(2, { message: "Company name must be at least 2 characters." })
    .max(100),
  logo: z
    .string()
    .url({ message: "Please enter a valid URL for the logo." })
    .optional()
    .or(z.literal("")),
  description: z
    .string()
    .max(500, { message: "Description cannot exceed 500 characters." })
    .optional()
    .or(z.literal("")),
  website: z
    .string()
    .url({ message: "Please enter a valid URL for the website." })
    .optional()
    .or(z.literal("")),
});

type CompanyFormValues = z.infer<typeof companyFormSchema>;

/**
 * Renders a form for users to submit information about a new company.
 *
 * This component handles the entire submission process:
 * - Displays input fields for the company's name, logo, description, and website.
 * - Enforces validation rules, such as minimum name length and valid URLs for optional fields.
 * - Shows a loading state on the submit button during the submission process.
 * - Calls the `addCompanyAction` server action with the form data.
 * - Displays success or error notifications (toasts) to the user.
 * - Resets the form upon successful submission.
 *
 * @returns {JSX.Element} The rendered company submission form.
 */
export default function CompanySubmissionForm() {
  const { toast } = useToast();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const form = useForm<CompanyFormValues>({
    resolver: zodResolver(companyFormSchema),
    defaultValues: {
      name: "",
      logo: "",
      description: "",
      website: "",
    },
  });

  const nameValue = form.watch("name");
  const descriptionValue = form.watch("description");
  const nameLength = nameValue ? nameValue.length : 0;
  const descriptionLength = descriptionValue ? descriptionValue.length : 0;

  async function onSubmit(data: CompanyFormValues) {
    setIsSubmitting(true);
    toast({
      title: "Submitting Company...",
      description: "Please wait while we add the company.",
    });

    const companyData: Omit<Company, "id"> = {
      name: data.name,
      slug: slugify(data.name),
      normalizedName: data.name.toLowerCase(),
      logo: data.logo === "" ? undefined : data.logo,
      description: data.description === "" ? undefined : data.description,
      website: data.website === "" ? undefined : data.website,
    };

    const result = await addCompanyAction(companyData);

    setIsSubmitting(false);
    if (result.success && result.data) {
      toast({
        title: "Company Added! 🎉",
        description: `"${result.data.name}" has been added successfully.`,
      });
      form.reset();
    } else {
      toast({
        title: "Submission Failed",
        description:
          result.error?.message || "An unknown error occurred. Please try again.",
        variant: "destructive",
      });
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">
        <FormField
          control={form.control}
          name="name"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex justify-between items-center">
                <span>
                  Company Name <span className="text-destructive">*</span>
                </span>
                <span
                  id="name-counter"
                  className={cn(
                    "text-xs text-muted-foreground font-normal",
                    nameLength >= 100 && "text-destructive font-medium",
                  )}
                >
                  {nameLength}/100
                  <span className="sr-only">characters used out of 100</span>
                </span>
              </FormLabel>
              <FormControl>
                <Input
                  placeholder="e.g., Awesome Tech Inc."
                  autoComplete="organization"
                  aria-describedby="name-counter"
                  {...field}
                />
              </FormControl>
              <FormDescription>
                The official name of the company.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="logo"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Logo URL (Optional)</FormLabel>
              <FormControl>
                <Input
                  type="url"
                  inputMode="url"
                  autoComplete="url"
                  placeholder="https://example.com/logo.png"
                  {...field}
                />
              </FormControl>
              <FormDescription>
                A direct URL to the company&apos;s logo. Leave blank if not
                available.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="description"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex justify-between items-center">
                Description (Optional)
                <span
                  id="description-counter"
                  className={cn(
                    "text-xs text-muted-foreground font-normal",
                    descriptionLength >= 500 && "text-destructive font-medium",
                  )}
                >
                  {descriptionLength}/500
                  <span className="sr-only">characters used out of 500</span>
                </span>
              </FormLabel>
              <FormControl>
                <Textarea
                  placeholder="e.g., Specializes in cutting-edge AI solutions."
                  className="resize-none"
                  aria-describedby="description-counter"
                  {...field}
                />
              </FormControl>
              <FormDescription>
                A short description of the company or what they are known for in
                interviews.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="website"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex items-center">
                <LinkIcon className="mr-2 h-4 w-4 text-muted-foreground" />
                Website URL (Optional)
              </FormLabel>
              <FormControl>
                <Input
                  type="url"
                  inputMode="url"
                  autoComplete="url"
                  placeholder="https://example.com"
                  {...field}
                />
              </FormControl>
              <FormDescription>
                The official website of the company. Leave blank if not
                available.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />

        <Button
          type="submit"
          disabled={isSubmitting}
          className="w-full sm:w-auto"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Adding Company...
            </>
          ) : (
            <>
              <PlusCircle className="mr-2 h-4 w-4" />
              Add Company
            </>
          )}
        </Button>
      </form>
    </Form>
  );
}

