// Define Supabase User Row type locally if not imported
export interface SupabaseUserRow {
  uid: string;
  email: string | null;
  display_name: string | null;
  photo_url: string | null;
  preferences: any | null;
  created_at: string;
  updated_at: string;
  last_synced_at?: string;
}

export type UserDocument = SupabaseUserRow;

export class UserMapper {
  static toDomain(row: SupabaseUserRow): User {
    return new User(
      {
        email: row.email ?? "",
        displayName: row.display_name ?? "",
        photoUrl: row.photo_url ?? undefined,
        preferences: row.preferences ?? {},
        createdAt: new Date(row.created_at),
        updatedAt: new Date(row.updated_at),
      },
      row.uid
    );
  }

  static toDTO(user: User): UserDTO {
    return {
      uid: user.id,
      email: user.email ?? "",
      displayName: user.displayName ?? "",
      photoUrl: user.photoUrl,
      preferences: user.preferences,
      createdAt: user.createdAt.toISOString(),
      updatedAt: user.updatedAt.toISOString(),
    };
  }

  static toRow(user: User): SupabaseUserRow {
    return {
      uid: user.id,
      email: user.email,
      display_name: user.displayName,
      photo_url: user.photoUrl ?? null,
      preferences: user.preferences,
      created_at: user.createdAt.toISOString(),
      updated_at: user.updatedAt.toISOString(),
      last_synced_at: user.lastSyncedAt?.toISOString(),
    };
  }

  static rowToDTO(row: SupabaseUserRow): UserDTO {
    return {
      uid: row.uid,
      email: row.email ?? "",
      displayName: row.display_name ?? "",
      photoUrl: row.photo_url ?? undefined,
      preferences: row.preferences ?? {},
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

/**
 * Bookmark Operations Module
 * Handles bookmark CRUD operations
 */

import { createSupabaseBrowserClient } from "@/shared/lib/api/supabase-browser";
import { Logger } from "@/shared/lib/utils/logger";
import type { BookmarkedProblemInfo } from "@/shared/types";

const MAX_PAGE_SIZE = 50;

/**
 * Interface for bookmark operations
 */
export interface BookmarkOperations {
  /**
   * Get bookmarked problems info for a user
   */
  getBookmarkedProblemsInfo(userId: string): Promise<BookmarkedProblemInfo[]>;

  /**
   * Toggle bookmark status for a problem
   */
  toggleBookmarkProblem(
    userId: string,
    problemId: string,
    companySlug: string,
    problemSlug: string
  ): Promise<{ isBookmarked: boolean; error?: string }>;
}

/**
 * Implementation of bookmark operations
 */
export class BookmarkOperationsImpl implements BookmarkOperations {
  private supabase = createSupabaseBrowserClient();

  /**
   * Get bookmarked problems info for a user
   * @param userId - The user's unique identifier
   * @returns Array of bookmarked problem info
   */
  async getBookmarkedProblemsInfo(userId: string): Promise<BookmarkedProblemInfo[]> {
    if (!userId) {
      return [];
    }
    try {
      // Fetch bookmarks with problem details and associated companies
      // We aim to get at least one company slug to construct a valid URL
      const { data, error } = await this.supabase
        .from("user_bookmarks")
        .select(`
          created_at,
          problem_id,
          problems (
            slug,
            company_problems (
              companies (
                slug
              )
            )
          )
        `)
        .eq("uid", userId)
        .order("created_at", { ascending: false })
        .limit(MAX_PAGE_SIZE);

      if (error) {
        throw error;
      }

      if (!data) {return [];}

      return data
        .map((row: any) => {
          const problem = row.problems;
          // Try to find a company slug from the joined data
          // company_problems is an array of { companies: { slug: string } }
          const companySlug = problem?.company_problems?.[0]?.companies?.slug;
          
          if (!problem?.slug || !companySlug) {
            return null; // Skip if data is incomplete
          }

          return {
            problemId: row.problem_id,
            companySlug: companySlug,
            problemSlug: problem.slug,
            bookmarkedAt: new Date(row.created_at),
          } as BookmarkedProblemInfo;
        })
        .filter((info): info is BookmarkedProblemInfo => info !== null);
    } catch (error) {
      Logger.error(`Error fetching bookmarked problems info`, error, { userId });
      return [];
    }
  }

  /**
   * Toggle bookmark status for a problem
   * @param userId - The user's unique identifier
   * @param problemId - The problem's unique identifier
   * @param companySlug - The company's slug
   * @param problemSlug - The problem's slug
   * @returns Result with bookmark status or error
   */
  async toggleBookmarkProblem(
    userId: string,
    problemId: string,
  ): Promise<{ isBookmarked: boolean; error?: string }> {
    if (!userId || !problemId) {
      return {
        isBookmarked: false,
        error: "User ID and Problem ID are required.",
      };
    }

    try {
      // Check if bookmark exists
      const { data: existing, error: checkError } = await this.supabase
        .from("user_bookmarks")
        .select("problem_id")
        .eq("uid", userId)
        .eq("problem_id", problemId)
        .single();

      if (checkError && checkError.code !== "PGRST116") {
        throw checkError;
      }

      if (existing) {
        // Delete if exists
        const { error: deleteError } = await this.supabase
          .from("user_bookmarks")
          .delete()
          .eq("uid", userId)
          .eq("problem_id", problemId);

        if (deleteError) {throw deleteError;}
        
        return { isBookmarked: false };
      } else {
        // Insert if not exists
        // Note: we don't store slugs in user_bookmarks table, relying on relational storage
        const { error: insertError } = await this.supabase
          .from("user_bookmarks")
          .insert({
            uid: userId,
            problem_id: problemId,
            notes: null // notes can be added later
          });

        if (insertError) {throw insertError;}

        return { isBookmarked: true };
      }
    } catch (error) {
      Logger.error("Error toggling bookmark in Supabase", error);
      return {
        isBookmarked: false,
        error: "An unexpected error occurred while toggling bookmark.",
      };
    }
  }
}

/**
 * Problem Status Operations Module
 * Handles problem status CRUD operations
 */

import { createSupabaseBrowserClient } from "@/shared/lib/api/supabase-browser";
import { Logger } from "@/shared/lib/utils/logger";
import type { ProblemStatus, UserProblemStatusInfo } from "@/shared/types";

/**
 * Interface for problem status operations
 */
export interface StatusOperations {
  /**
   * Get all problem statuses for a user
   */
  getAllUserProblemStatuses(userId: string): Promise<Record<string, UserProblemStatusInfo>>;

  /**
   * Get user's global problem stats
   */
  getUserGlobalProblemStats(userId: string): Promise<{
    solvedProblemIds: string[];
    attemptedProblemIds: string[];
    bookmarkedProblemIds: string[];
  }>;

  /**
   * Set problem status for a user
   */
  setProblemStatus(
    userId: string,
    problemId: string,
    status: ProblemStatus,
    companySlug: string,
    problemSlug: string
  ): Promise<{ success: boolean; error?: string }>;
}

/**
 * Implementation of problem status operations
 */
export class StatusOperationsImpl implements StatusOperations {
  private supabase = createSupabaseBrowserClient();

  /**
   * Get all problem statuses for a user
   * @param userId - The user's unique identifier
   * @returns Record of problem ID to status info
   */
  async getAllUserProblemStatuses(
    userId: string
  ): Promise<Record<string, UserProblemStatusInfo>> {
    if (!userId) {
      return {};
    }
    const statuses: Record<string, UserProblemStatusInfo> = {};
    try {
      const { data, error } = await this.supabase
        .from("user_problem_status")
        .select(`
          problem_id,
          status,
          updated_at,
          problems (
            slug,
            company_problems (
               companies (
                 slug
               )
            )
          )
        `)
        .eq("uid", userId)
        .order("updated_at", { ascending: false });

      if (error) {
        throw error;
      }

      if (data) {
        data.forEach((row: any) => {
          const problem = row.problems;
          // Determine company slug from available relationships
          const companySlug = problem?.company_problems?.[0]?.companies?.slug;
          
           if (row.problem_id && row.status && problem?.slug && companySlug) {
              statuses[row.problem_id] = {
                problemId: row.problem_id,
                status: row.status as ProblemStatus,
                companySlug: companySlug,
                problemSlug: problem.slug,
                updatedAt: new Date(row.updated_at),
              };
           }
        });
      }
      return statuses;
    } catch (error) {
      Logger.error(`Error fetching all problem statuses`, error, { userId });
      return {};
    }
  }

  /**
   * Get user's global problem stats
   * @param userId - The user's unique identifier
   * @returns User's global problem stats
   */
  async getUserGlobalProblemStats(userId: string): Promise<{
    solvedProblemIds: string[];
    attemptedProblemIds: string[];
    bookmarkedProblemIds: string[];
  }> {
    if (!userId) {
      return { solvedProblemIds: [], attemptedProblemIds: [], bookmarkedProblemIds: [] };
    }
    try {
      // Execute 3 parallel queries to get the stats
      const [solvedRes, attemptedRes, bookmarkRes] = await Promise.all([
        this.supabase
          .from("user_problem_status")
          .select("problem_id")
          .eq("uid", userId)
          .eq("status", "solved"),
        this.supabase
          .from("user_problem_status")
          .select("problem_id")
          .eq("uid", userId)
          .in("status", ["attempted", "in_progress"]), // Assuming these count as attempted
        this.supabase
          .from("user_bookmarks")
          .select("problem_id")
          .eq("uid", userId)
      ]);

      if (solvedRes.error) {throw solvedRes.error;}
      if (attemptedRes.error) {throw attemptedRes.error;}
      if (bookmarkRes.error) {throw bookmarkRes.error;}

      return {
        solvedProblemIds: solvedRes.data?.map(r => r.problem_id) || [],
        attemptedProblemIds: attemptedRes.data?.map(r => r.problem_id) || [],
        bookmarkedProblemIds: bookmarkRes.data?.map(r => r.problem_id) || [],
      };
    } catch (error) {
      Logger.error(`Error fetching global problem stats`, error, { userId });
      return { solvedProblemIds: [], attemptedProblemIds: [], bookmarkedProblemIds: [] };
    }
  }

  /**
   * Set problem status for a user
   * @param userId - The user's unique identifier
   * @param problemId - The problem's unique identifier
   * @param status - The new status
   * @param companySlug - The company's slug
   * @param problemSlug - The problem's slug
   * @returns Result indicating success or error
   */
  async setProblemStatus(
    userId: string,
    problemId: string,
    status: ProblemStatus
  ): Promise<{ success: boolean; error?: string }> {
    if (!userId || !problemId) {
      return { success: false, error: "User ID and Problem ID are required." };
    }

    try {
      if (status === "none") {
        // Remove status
        const { error } = await this.supabase
          .from("user_problem_status")
          .delete()
          .eq("uid", userId)
          .eq("problem_id", problemId);
          
        if (error) {throw error;}
      } else {
        // Upsert status
        const updates: any = {
           uid: userId,
           problem_id: problemId,
           status: status,
           updated_at: new Date().toISOString()
        };

        if (status === 'solved') {
            updates.solved_at = new Date().toISOString();
        } else if (status === 'attempted' || status === 'in_progress') {
            updates.last_attempted_at = new Date().toISOString();
        }

        const { error } = await this.supabase
          .from("user_problem_status")
          .upsert(updates, { onConflict: "uid,problem_id" });

        if (error) {throw error;}
      }

      return { success: true };
    } catch (error) {
      Logger.error("Error setting problem status in Supabase", error);
      return {
        success: false,
        error: "An unexpected error occurred while updating problem status.",
      };
    }
  }
}

/**
 * Problem Status Queries Module
 * Handles problem status query operations
 */

import { createSupabaseBrowserClient } from "@/shared/lib/api/supabase-browser";
import { Logger } from "@/shared/lib/utils/logger";
import type { ProblemStatus, UserProblemStatusInfo } from "@/shared/types";

/**
 * Interface for problem status query operations
 */
export interface StatusQueries {
  /**
   * Get problem statuses for specific problem IDs
   */
  getProblemStatusesForIds(
    userId: string,
    problemIds: string[]
  ): Promise<Record<string, UserProblemStatusInfo>>;
}

/**
 * Implementation of problem status query operations
 */
export class StatusQueriesImpl implements StatusQueries {
  private supabase = createSupabaseBrowserClient();

  /**
   * Get problem statuses for specific problem IDs
   * @param userId - The user's unique identifier
   * @param problemIds - Array of problem IDs to fetch statuses for
   * @returns Record of problem ID to status info
   */
  async getProblemStatusesForIds(
    userId: string,
    problemIds: string[]
  ): Promise<Record<string, UserProblemStatusInfo>> {
    if (!userId || !problemIds || problemIds.length === 0) {
      return {};
    }
    const statuses: Record<string, UserProblemStatusInfo> = {};

    try {
      const { data, error } = await this.supabase
        .from("user_problem_status")
        .select(`
          problem_id,
          status,
          updated_at,
          problems (
            slug,
            company_problems (
              companies (
                slug
              )
            )
          )
        `)
        .eq("uid", userId)
        .in("problem_id", problemIds);

      if (error) {
        throw error;
      }

      if (data) {
        data.forEach((row: any) => {
           const problem = row.problems;
           const companySlug = problem?.company_problems?.[0]?.companies?.slug;
           
           if (row.problem_id && row.status && problem?.slug && companySlug) {
            statuses[row.problem_id] = {
              problemId: row.problem_id,
              status: row.status as ProblemStatus,
              companySlug: companySlug,
              problemSlug: problem.slug,
              updatedAt: new Date(row.updated_at),
            };
           }
        });
      }

      return statuses;
    } catch (error) {
      Logger.error(`Error fetching problem statuses`, error, { userId });
      return {};
    }
  }
}

/**
 * Strategy Operations Module
 * Handles strategy CRUD operations
 */

import { createSupabaseBrowserClient } from "@/shared/lib/api/supabase-browser";
import { Logger } from "@/shared/lib/utils/logger";
import type {
  FocusTopic,
  GenerateCompanyStrategyOutput,
  SavedStrategyTodoList,
  StrategyTodoItem,
} from "@/shared/types";

/**
 * Interface for strategy operations
 */
export interface StrategyOperations {
  /**
   * Get strategy todo list for a specific company
   */
  getStrategyTodoListForCompany(
    userId: string,
    companyId: string
  ): Promise<SavedStrategyTodoList | null>;

  /**
   * Save strategy todo list for a company
   */
  saveStrategyTodoList(
    userId: string,
    companyId: string,
    companyName: string,
    strategyData: Pick<
      GenerateCompanyStrategyOutput,
      "preparationStrategy" | "focusTopics" | "todoItems"
    >
  ): Promise<{ success: boolean; error?: string }>;

  /**
   * Update status of a todo item in a strategy list
   */
  updateStrategyTodoItemStatus(
    userId: string,
    companyId: string,
    itemIndex: number,
    isCompleted: boolean
  ): Promise<{ success: boolean; error?: string }>;
}

/**
 * Implementation of strategy operations
 */
export class StrategyOperationsImpl implements StrategyOperations {
  private supabase = createSupabaseBrowserClient();

  /**
   * Get strategy todo list for a specific company
   * @param userId - The user's unique identifier
   * @param companyId - The company's unique identifier
   * @returns The strategy todo list if found, null otherwise
   */
  async getStrategyTodoListForCompany(
    userId: string,
    companyId: string
  ): Promise<SavedStrategyTodoList | null> {
    if (!userId || !companyId) {
      return null;
    }
    
    try {
      const { data, error } = await this.supabase
        .from("user_strategies")
        .select("*")
        .eq("uid", userId)
        .eq("company_id", companyId)
        .single();

      if (error && error.code !== "PGRST116") {
        throw error;
      }

      if (!data) {return null;}

      // Map snake_case to domain object
      return {
        companyId: data.company_id || companyId,
        companyName: data.company_name || "Unknown Company",
        savedAt: data.saved_at ? new Date(data.saved_at) : new Date(data.created_at || Date.now()),
        preparationStrategy: data.preparation_strategy || "",
        focusTopics: (data.focus_topics as FocusTopic[]) || [],
        items: (data.todo_items as StrategyTodoItem[]) || [],
      } as SavedStrategyTodoList;
    } catch (error) {
      Logger.error(`Error fetching strategy`, error, { companyId, userId });
      return null;
    }
  }

  /**
   * Save strategy todo list for a company
   * @param userId - The user's unique identifier
   * @param companyId - The company's unique identifier
   * @param companyName - The company's name
   * @param strategyData - The strategy data to save
   * @returns Result indicating success or error
   */
  async saveStrategyTodoList(
    userId: string,
    companyId: string,
    companyName: string,
    strategyData: Pick<
      GenerateCompanyStrategyOutput,
      "preparationStrategy" | "focusTopics" | "todoItems"
    >
  ): Promise<{ success: boolean; error?: string }> {
    if (!userId || !companyId) {
      return { success: false, error: "User ID and Company ID are required." };
    }
    
    try {
      // Check if exists
      const { data: existing } = await this.supabase
        .from("user_strategies")
        .select("id")
        .eq("uid", userId)
        .eq("company_id", companyId)
        .single();
        
      const dbRow = {
        uid: userId,
        company_id: companyId,
        company_name: companyName,
        preparation_strategy: strategyData.preparationStrategy,
        focus_topics: strategyData.focusTopics, // Supabase handles JSON array automatically
        todo_items: strategyData.todoItems,
        saved_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      if (existing) {
         // Update
         const { error } = await this.supabase
          .from("user_strategies")
          .update(dbRow)
          .eq("id", existing.id);
          
         if (error) {throw error;}
      } else {
         // Insert
         const { error } = await this.supabase
          .from("user_strategies")
          .insert(dbRow);
          
         if (error) {throw error;}
      }

      return { success: true };
    } catch (error) {
      Logger.error("Error saving strategy to Supabase", error);
      return { success: false, error: "An unexpected error occurred while saving strategy." };
    }
  }

  /**
   * Update status of a todo item in a strategy list
   * @param userId - The user's unique identifier
   * @param companyId - The company's unique identifier
   * @param itemIndex - The index of the item to update
   * @param isCompleted - The new completion status
   * @returns Result indicating success or error
   */
  async updateStrategyTodoItemStatus(
    userId: string,
    companyId: string,
    itemIndex: number,
    isCompleted: boolean
  ): Promise<{ success: boolean; error?: string }> {
    if (!userId || !companyId || itemIndex < 0) {
      return {
        success: false,
        error: "Invalid parameters for updating todo item.",
      };
    }
    
    try {
      // 1. Fetch existing items
      const { data, error: fetchError } = await this.supabase
        .from("user_strategies")
        .select("id, todo_items")
        .eq("uid", userId)
        .eq("company_id", companyId)
        .single();

      if (fetchError || !data) {
         return { success: false, error: "Todo list not found." };
      }

      const items = (data.todo_items as any[]) || [];
      
      if (itemIndex >= items.length) {
         return { success: false, error: "Item index out of bounds." };
      }

      // 2. Modify item
      items[itemIndex].isCompleted = isCompleted;

      // 3. Update
      const { error: updateError } = await this.supabase
        .from("user_strategies")
        .update({
           todo_items: items,
           updated_at: new Date().toISOString() // saved_at might be preserved or updated? sticking to updated_at
        })
        .eq("id", data.id);

      if (updateError) {throw updateError;}
      
      return { success: true };
    } catch (error) {
      Logger.error("Error updating todo item status in Supabase", error);
      return {
        success: false,
        error: "An unexpected error occurred while updating todo item.",
      };
    }
  }
}

/**
 * User Operations Module
 * Handles core user CRUD operations
 */

import { User as UserEntity } from "@/core/domain/entities/user.entity";
import { createSupabaseBrowserClient } from "@/shared/lib/api/supabase-browser";
import { Logger } from "@/shared/lib/utils/logger";

import type {
  CreateUserDTO,
  UpdateUserDTO,
} from "../../interfaces/user.repository.interface";
import { UserMapper } from "../../mappers/user.mapper";

/**
 * Interface for user operations
 */
export interface UserOperations {
  /**
   * Find a user by their unique identifier
   */
  findById(id: string): Promise<UserEntity | null>;

  /**
   * Save a new user
   */
  save(data: CreateUserDTO): Promise<UserEntity>;

  /**
   * Update an existing user
   */
  update(id: string, data: UpdateUserDTO): Promise<UserEntity>;

  /**
   * Delete a user by their unique identifier
   */
  delete(id: string): Promise<void>;

  /**
   * Check if a user exists by their unique identifier
   */
  exists(id: string): Promise<boolean>;

  /**
   * Update user's display name
   */
  updateUserDisplayName(
    userId: string,
    newDisplayName: string
  ): Promise<{ success: boolean; error?: string }>;

  /**
   * Sync user profile from authentication provider
   */
  syncUserProfile(
    email: string | null,
    displayName: string | null
  ): Promise<{ success: boolean; error?: string }>;
}

/**
 * Implementation of user operations
 */
export class UserOperationsImpl implements UserOperations {
  private supabase = createSupabaseBrowserClient();

  /**
   * Find a user by their unique identifier
   * @param id - The user's unique identifier (uid)
   * @returns The User entity if found, null otherwise
   */
  async findById(id: string): Promise<UserEntity | null> {
    if (!id) {
      return null;
    }
    try {
      const { data, error } = await this.supabase
        .from("users")
        .select("*")
        .eq("uid", id)
        .single();

      if (error || !data) {
        // PGRST116 code indicates 0 rows returned for single()
        if (error?.code !== "PGRST116") {
            Logger.error("Error fetching user by ID", error, { id });
        }
        return null;
      }
    
      return UserMapper.toDomain(data);
    } catch (error) {
      Logger.error("Error fetching user by ID", error, { id });
      return null;
    }
  }

  /**
   * Save a new user
   * @param data - The data to create the user with
   * @returns The created User entity
   */
  async save(data: CreateUserDTO): Promise<UserEntity> {
    try {
      const { data: { user: currentUser } } = await this.supabase.auth.getUser();
      if (!currentUser) {
        throw new Error("User is not authenticated");
      }

      if (data.displayName) {
        // Security: Validate display name to prevent stored XSS or injection
        if (/[<>]/.test(data.displayName)) {
          throw new Error("Display name contains invalid characters.");
        }
      }

      const uid = currentUser.id;
      
      const userEntity = UserEntity.create(
        {
          email: data.email,
          displayName: data.displayName,
          photoUrl: data.photoUrl,
          preferences: data.preferences ?? {},
        },
        uid
      );

      const row = UserMapper.toRow(userEntity);

      const { error } = await this.supabase
        .from("users")
        .insert(row);

      if (error) {
        throw new Error(error.message);
      }

      return userEntity;
    } catch (error) {
      Logger.error("Error saving user", error);
      throw error;
    }
  }

  /**
   * Update an existing user
   * @param id - The user's unique identifier
   * @param data - The data to update
   * @returns The updated User entity
   */
  async update(id: string, data: UpdateUserDTO): Promise<UserEntity> {
    try {
      const updates: any = {
        updated_at: new Date().toISOString(),
      };

      if (data.email !== undefined) {updates.email = data.email;}
      if (data.displayName !== undefined) {
         if (data.displayName && /[<>]/.test(data.displayName)) {
           throw new Error("Display name contains invalid characters.");
         }
         updates.display_name = data.displayName;
      }
      if (data.photoUrl !== undefined) {updates.photo_url = data.photoUrl;}
      if (data.preferences !== undefined) {updates.preferences = data.preferences;}

      const { error } = await this.supabase
        .from("users")
        .update(updates)
        .eq("uid", id);

      if (error) {
        throw new Error(error.message);
      }

      const updatedUser = await this.findById(id);
      if (!updatedUser) {
        throw new Error("User not found after update");
      }

      return updatedUser;
    } catch (error) {
      Logger.error("Error updating user", error, { id });
      throw error;
    }
  }

  /**
   * Delete a user by their unique identifier
   * @param id - The user's unique identifier
   */
  async delete(id: string): Promise<void> {
    try {
      const { error } = await this.supabase
        .from("users")
        .delete()
        .eq("uid", id);

      if (error) {
        throw new Error(error.message);
      }
    } catch (error) {
      Logger.error("Error deleting user", error, { id });
      throw error;
    }
  }

  /**
   * Check if a user exists by their unique identifier
   * @param id - The user's unique identifier
   * @returns True if the user exists, false otherwise
   */
  async exists(id: string): Promise<boolean> {
    if (!id) {
      return false;
    }
    try {
       const { count, error } = await this.supabase
        .from("users")
        .select("uid", { count: "exact", head: true })
        .eq("uid", id);
      
      if (error) {
           return false;
      }
      return (count ?? 0) > 0;
    } catch (error) {
      Logger.error("Error checking user existence", error, { id });
      return false;
    }
  }

  /**
   * Update user's display name
   * @param userId - The user's unique identifier
   * @param newDisplayName - The new display name
   * @returns Result indicating success or error
   */
  async updateUserDisplayName(
    userId: string,
    newDisplayName: string
  ): Promise<{ success: boolean; error?: string }> {
    if (!userId) {
      return { success: false, error: "User ID is required." };
    }

    const trimmedName = newDisplayName ? newDisplayName.trim() : "";

    if (trimmedName.length < 2) {
      return {
        success: false,
        error: "Display name must be at least 2 characters.",
      };
    }
    if (trimmedName.length > 50) {
      return {
        success: false,
        error: "Display name must be less than 50 characters.",
      };
    }

    if (/[<>]/.test(trimmedName)) {
      Logger.warn("Blocked attempt to set display name with invalid characters", {
        userId,
        displayName: trimmedName,
      });
      return {
        success: false,
        error: "Display name contains invalid characters.",
      };
    }

    try {
      const { error } = await this.supabase
        .from("users")
        .update({ display_name: trimmedName, updated_at: new Date().toISOString() })
        .eq("uid", userId);

      if (error) {
          throw new Error(error.message);
      }
      return { success: true };
    } catch (error) {
      Logger.error("Error updating user display name in Supabase", error);
      return {
        success: false,
        error: "An unexpected error occurred while updating display name.",
      };
    }
  }

  /**
   * Sync user profile from authentication provider
   * @param email - The user's email
   * @param displayName - The user's display name
   * @returns Result indicating success or error
   */
  async syncUserProfile(
    email: string | null,
    displayName: string | null
  ): Promise<{ success: boolean; error?: string }> {
    try {
      const { data: { user: currentUser } } = await this.supabase.auth.getUser();
      if (!currentUser) {
        return { success: false, error: "User is not authenticated." };
      }
      const uid = currentUser.id;

      const updates: any = {
        uid,
        last_synced_at: new Date().toISOString(),
      };

      // Only update fields if they are provided/changed? 
      // Upsert will handle create or update.
      // We want to ensure specific fields are set.
      
      if (currentUser.email) {
        updates.email = currentUser.email;
      } else if (email) {
        updates.email = email;
      }

      if (displayName) {
        let safeName = displayName.trim();
        if (safeName.length > 50) {
          safeName = safeName.substring(0, 50);
        }
        if (/[<>]/.test(safeName)) {
          safeName = safeName.replace(/[<>]/g, "");
        }
        if (safeName.length > 0) {
          updates.display_name = safeName;
        }
      }
      
      // Upsert: Create if not exists, update if exists
      // We do NOT update created_at, but we update last_synced_at
      const { error } = await this.supabase
        .from("users")
        .upsert(updates, { onConflict: "uid" });

      if (error) {
          throw new Error(error.message);
      }

      return { success: true };
    } catch (error) {
      Logger.error("Error syncing user profile to Supabase", error);
      return {
        success: false,
        error: "An unexpected error occurred while syncing user profile.",
      };
    }
  }
}

export interface UserDTO {
  uid: string;
  email: string;
  displayName: string;
  photoUrl?: string;
  preferences: Record<string, any>;
  createdAt: string;
  updatedAt: string;
}

