/**
 * @fileoverview Hook for handling hydration-safe client-side rendering.
 * 
 * This hook ensures that client-specific content is only rendered after
 * hydration completes, preventing hydration mismatches between server and client.
 */
"use client";

import { useEffect, useState } from "react";

/**
 * Hook that returns true only after the component has hydrated on the client.
 * Use this to defer rendering of client-specific content until after hydration.
 * 
 * @returns {boolean} True if the component has hydrated, false otherwise
 * 
 * @example
 * ```tsx
 * function MyComponent() {
 *   const isHydrated = useHydrationSafe();
 *   
 *   if (!isHydrated) {
 *     return <div>Loading...</div>; // Server and initial client render
 *   }
 *   
 *   return <div>{clientOnlyContent}</div>; // Only after hydration
 * }
 * ```
 */
export function useHydrationSafe(): boolean {
  const [isHydrated, setIsHydrated] = useState(false);

  useEffect(() => {
    // This effect only runs on the client after hydration
    setIsHydrated(true);
  }, []);

  return isHydrated;
}

/**
 * Hook that safely handles layout effects during SSR.
 * Uses useEffect on server and useLayoutEffect on client.
 * 
 * This prevents warnings about useLayoutEffect during SSR while
 * maintaining proper timing on the client.
 */
export const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useEffect : useEffect;

import type React from "react";

import type { AppRouterInstance } from "next/dist/shared/lib/app-router-context.shared-runtime";

import { type User } from "@supabase/supabase-js";

import { authService } from "@/features/auth/services/auth.service";
import type { ToastFunction } from "@/shared/hooks/use-toast";

export type NavigationPosition = "main" | "auth" | "mobile-bottom";

export interface NavigationContext {
  user: User | null;
  isLoading: boolean;
}

export interface NavigationActionContext {
  router: AppRouterInstance;
  toast: ToastFunction;
}

export interface NavigationRenderContext extends NavigationContext {
  isMobile: boolean;
}

export interface NavigationItem {
  key: string;
  label: string;
  href?: string;
  onClick?: (context: NavigationActionContext) => void | Promise<void>; 
  render?: (context: NavigationRenderContext) => React.ReactNode;
  position: NavigationPosition;
  order?: number;
  isVisible?: (context: NavigationContext) => boolean;
  className?: string; // Allow custom styling extensions
}

class NavigationRegistry {
  private items: NavigationItem[] = [];

  register(item: NavigationItem) {
    // Prevent duplicates by key
    const existingIndex = this.items.findIndex((i) => i.key === item.key);
    if (existingIndex >= 0) {
        this.items[existingIndex] = item;
    } else {
        this.items.push(item);
    }
  }

  unregister(key: string) {
    this.items = this.items.filter((i) => i.key !== key);
  }

  getItems(position: NavigationPosition, context: NavigationContext): NavigationItem[] {
    return this.items
      .filter((item) => item.position === position)
      .filter((item) => (item.isVisible ? item.isVisible(context) : true))
      .sort((a, b) => (a.order || 0) - (b.order || 0));
  }
}

export const navigationRegistry = new NavigationRegistry();

// Initialize default navigation items
// This mimics "core" logic registering its own items
navigationRegistry.register({
  key: "companies",
  label: "Explore Companies",
  href: "/companies",
  position: "main",
  order: 10,
});

navigationRegistry.register({
  key: "problems",
  label: "Problems",
  href: "/problems",
  position: "main",
  order: 20,
});

// Auth items are dynamic, so we'll register them with isVisible checks
navigationRegistry.register({
  key: "login",
  label: "Login",
  href: "/login",
  position: "auth",
  order: 10,
  isVisible: ({ user, isLoading }) => !isLoading && !user,
});

navigationRegistry.register({
  key: "signup",
  label: "Sign Up",
  href: "/signup",
  position: "auth",
  order: 20,
  isVisible: ({ user, isLoading }) => !isLoading && !user,
});

navigationRegistry.register({
  key: "profile",
  label: "Profile",
  href: "/profile",
  position: "auth",
  order: 10,
  isVisible: ({ user, isLoading }) => !isLoading && !!user,
});

// We can now safely register Logout here, as the handler will receive dependencies at runtime
navigationRegistry.register({
  key: "logout",
  label: "Logout",
  position: "auth",
  order: 100,
  isVisible: ({ user, isLoading }) => !isLoading && !!user,
  onClick: async ({ router, toast }) => {
    try {
      await authService.logout();
      toast.success("Logged Out", "You have been successfully logged out.");
      router.push("/");
    } catch (error) {
      console.error("Logout error:", error);
      toast.error("Logout Failed", "Could not log you out. Please try again.");
    }
  },
});
